import {escapeText as esc,icon,imageMarkup} from './assets.js';
import {knownValues,hasFieldEvidence} from './food-model.js';
import {roles,suggestedMeals,suggestedTastes,inspirationSummary,isMainInspiration} from './inspiration-model.js';
const mealNames={breakfast:'早餐',lunch:'午餐',dinner:'晚餐'};
import {recipeDetail} from './nutrition-view.js';
export function inspirationDetailMarkup(d,state,selectedMeal){
 const meals=suggestedMeals(d).filter(m=>isMainInspiration(d,m)),main=meals.length>0,flavors=suggestedTastes(d);
 return `<div class="detail-image"><div class="table-mat" aria-hidden="true"></div>${imageMarkup({...d,thumbnail:null},{lazy:false})}<span class="detail-photo-note">餐品示意，供应未核对</span></div><div class="detail-body"><div class="detail-kicker">${esc(d.category)}<span>${esc(roles[d.inspiration.mealRole])}</span></div><h2 id="detailTitle">${esc(d.name)}</h2><div class="dish-editorial"><p class="detail-intro">${esc(d.inspiration.description??inspirationSummary(d))}</p><div class="dish-choice-note"><h3>怎么选，怎么搭</h3><p>${esc(d.inspiration.choosingTip??'按食欲选择份量，并确认实际配料。')}</p></div></div><div class="tags">${flavors.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><dl class="dish-facts"><div><dt>建议餐次</dt><dd>${meals.map(m=>mealNames[m]).join('、')||'未指定'}</dd></div><div><dt>适合怎么选</dt><dd>${main?'作为一餐的备选灵感':'作为配菜、小食或甜点，搭配正餐选择'}</dd></div></dl>${main&&meals.length?`<label class="detail-meal-label">安排到 <select id="detailMeal">${meals.map(m=>`<option value="${m}" ${m===selectedMeal?'selected':''}>${mealNames[m]}</option>`).join('')}</select></label>`:'<p class="side-dish-note">这份作为加点灵感，不单独抽成正餐或排入周计划。</p>'}<div class="main-actions">${main&&meals.length?`<button class="button primary" data-action="decide" data-id="${d.id}">就吃这个 ${icon('check')}</button>`:''}<button class="button secondary favorite-button" data-action="favorite" data-id="${d.id}" aria-pressed="${state.favorites.includes(d.id)}">${icon('heart')}${state.favorites.includes(d.id)?'已收藏':'收藏这道'}</button><button class="icon-button" data-action="share" data-id="${d.id}" aria-label="分享${esc(d.name)}">${icon('arrow')}</button></div>${recipeDetail(d)}<p class="meal-suitability-note">${esc(d.mealSuitability?.note??'')}</p><div class="collection-add"><label for="detailFolder">加入收藏夹</label><select id="detailFolder">${state.collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select><button class="text-button" data-action="folder-add" data-id="${d.id}">加入</button></div><details class="inspiration-about"><summary>关于这份灵感</summary><p>这是通用菜品灵感，不绑定具体餐厅。图片、口味和建议餐次用于选餐参考，实际做法、份量、价格与供应以窗口为准。</p><p>决定只是安排，确认吃过后才计入个人用餐记录。</p></details></div>`;
}
export function verifiedDetailMarkup(d,state,selectedMeal){
 const meals=knownValues(d,'mealTypes'),tastes=knownValues(d,'tastes'),ingredients=knownValues(d,'ingredients'),v=d.verification;
 const arrange=meals.length?`<label class="detail-meal-label">安排到 <select id="detailMeal">${meals.map(m=>`<option value="${m}" ${m===selectedMeal?'selected':''}>${mealNames[m]}</option>`).join('')}</select></label>`:'<p class="archive-notice">餐次尚未确认，可以浏览和收藏，暂不提供本餐决定。</p>';
 return `<div class="detail-image">${imageMarkup({...d,thumbnail:null},{lazy:false})}</div><div class="detail-body"><div class="meta"><span>${esc(d.restaurant)}</span><span>${esc(d.category)}</span></div><h2 id="detailTitle">${esc(d.name)}</h2><dl class="dish-facts"><div><dt>餐次</dt><dd>${meals.length?meals.map(m=>mealNames[m]).join('、'):'尚未确认'}</dd></div><div><dt>口味</dt><dd>${tastes.length?esc(tastes.join('、')):'尚未确认'}</dd></div><div><dt>价格</dt><dd>${hasFieldEvidence(d,'price')&&d.price?esc(d.price.amount+'元/'+d.price.unit):'尚未确认'}</dd></div><div><dt>配料</dt><dd>${ingredients.length?esc(ingredients.join('、')):'尚未取得完整配料资料，请到窗口确认。'}</dd></div></dl>${d.components?.length?`<p>名称列出的组合：${esc(d.components.map(c=>c.name).join('＋'))}</p>`:''}<p>核实：${esc(v.checkedAt)}，资料有效至 ${esc(v.validUntil)}。非实时在售查询。</p><details><summary>菜品来源与字段依据</summary><ul class="source-list">${v.evidence.filter(e=>/^https:\/\//.test(e.url??'')).map(e=>`<li><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title||'查看证据')}</a>：${esc(e.locator)}<br>覆盖字段：${esc((e.fields??[]).join('、'))}</li>`).join('')}</ul></details><p class="small">餐品示意，非窗口实拍。</p>${arrange}<div class="main-actions">${meals.length?`<button class="button primary" data-action="decide" data-id="${esc(d.id)}">就吃这个</button>`:''}<button class="button secondary favorite-button" data-action="favorite" data-id="${esc(d.id)}" aria-pressed="${state.favorites.includes(d.id)}">${icon('heart')}${state.favorites.includes(d.id)?'已收藏':'收藏'}</button><button class="button secondary" data-action="share" data-id="${esc(d.id)}">分享菜品</button></div><label class="detail-meal-label">加入收藏夹 <select id="detailFolder">${state.collections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><button class="text-button" data-action="folder-add" data-id="${esc(d.id)}">加入所选收藏夹</button></div>`;
}
